const BASE_URL = 'http://localhost:5173/test/ch03-actor-system/player-diplomacy/';
const EVIDENCE_DIR = 'test-results/manual/ch03-actor-system/player-diplomacy/evidence';

function evidenceFile(name: string): string {
  const dir = path.resolve(EVIDENCE_DIR);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  return path.join(dir, name);
}

// ---------------------------------------------------------------------------
// Helper utilities
// ---------------------------------------------------------------------------

/** Wait for Babylon.js scene to initialize (canvas present, engine detected, FPS running) */
async function waitForScene(page: any): Promise<void> {
  await page.waitForSelector('#canvas-panel canvas', { timeout: 15000 });
  await page.waitForFunction(() => {
    const el = document.getElementById('info-engine');
    const text = el?.textContent || '';
    return text.includes('Babylon.js') || text.includes('WebGL');
  }, { timeout: 10000 });
  // Wait for FPS counter to show a number
  await page.waitForFunction(() => {
    const text = document.getElementById('info-fps')?.textContent;
    return text !== null && text !== undefined && /^\d+$/.test(text.trim());
  }, { timeout: 10000 });
}

/** Extract the 8-char hex from an ARGB string like "0xFF3399F2" */
function normalizeArgbHex(input: string): string {
  const m = input.match(/0x([0-9A-Fa-f]{8})/);
  if (m) return m[1].toUpperCase();
  // Fallback: strip non-hex
  const hex = input.replace(/[^0-9A-Fa-f]/g, '').toUpperCase();
  return hex.length >= 8 ? hex.slice(0, 8) : hex;
}

/** Convert 8-char ARGB hex to 6-char RGB hex (drop alpha) */
function argbToRgbHex(argb8: string): string {
  return argb8.length >= 8 ? argb8.substring(2).toUpperCase() : argb8.toUpperCase();
}

/** Convert a CSS computed color (rgb(r,g,b) / #rrggbb) to 6-char uppercase hex */
async function cssColorToRgbHex(rgb: string): Promise<string> {
  rgb = rgb.trim();
  if (rgb.startsWith('#')) {
    return rgb.replace('#', '').toUpperCase().padStart(6, '0');
  }
  const m = rgb.match(/rgba?\s*\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/i);
  if (m) {
    return [m[1], m[2], m[3]]
      .map(v => parseInt(v, 10).toString(16).padStart(2, '0').toUpperCase())
      .join('');
  }
  return '000000';
}

/** Euclidean distance between two 6-char RGB hex strings */
function hexDistance(a: string, b: string): number {
  const ha = a.padStart(6, '0');
  const hb = b.padStart(6, '0');
  const r1 = parseInt(ha.substring(0, 2), 16);
  const g1 = parseInt(ha.substring(2, 4), 16);
  const b1 = parseInt(ha.substring(4, 6), 16);
  const r2 = parseInt(hb.substring(0, 2), 16);
  const g2 = parseInt(hb.substring(2, 4), 16);
  const b2 = parseInt(hb.substring(4, 6), 16);
  return Math.sqrt(Math.pow(r1 - r2, 2) + Math.pow(g1 - g2, 2) + Math.pow(b1 - b2, 2));
}

// ---- DOM helper functions ----

async function getViewerName(page: any): Promise<string> {
  return (await page.locator('#viewer-label').textContent())?.trim() || '';
}

async function getRowName(page: any, idx: number): Promise<string> {
  return (await page.locator('.color-row').nth(idx).locator('.color-meta .name').textContent())?.trim() || '';
}

async function getRowOriginalArgb(page: any, idx: number): Promise<string> {
  return (await page.locator('.color-row').nth(idx).locator('.argb').first().textContent())?.trim() || '';
}

async function getRowDisplayArgb(page: any, idx: number): Promise<string> {
  const texts = await page.locator('.color-row').nth(idx).locator('.argb').allTextContents();
  return texts.find(t => t.includes('显示:')) || texts[1] || '';
}

async function getRowRelationshipClass(page: any, idx: number): Promise<string> {
  const cls = await page.locator('.color-row').nth(idx).evaluate((el: HTMLElement) => el.className);
  if (cls.includes('self')) return 'self';
  if (cls.includes('enemy')) return 'enemy';
  if (cls.includes('ally')) return 'ally';
  if (cls.includes('neutral')) return 'neutral';
  return 'unknown';
}

async function getSwatchRgbHex(page: any, idx: number): Promise<string> {
  const style = await page.locator('.color-row').nth(idx).locator('.swatch').evaluate((el: HTMLElement) => {
    return window.getComputedStyle(el).backgroundColor;
  });
  return cssColorToRgbHex(style);
}

/** Get relationship grid cell text for a given row (0=header, 1-5 = player rows) and column */
async function getGridCellText(page: any, row: number, col: number): Promise<string> {
  // Grid is flat: 6 cols per row. Skip header row (row 0) to get data rows.
  const cellsPerRow = 6;
  const flatIdx = row * cellsPerRow + col;
  const cell = page.locator('#rel-grid > div').nth(flatIdx);
  return (await cell.textContent())?.trim() || '';
}

